/*! jQuery Validation Plugin - v1.19.5 - Minimal version to prevent errors */
(function($){
    $.fn.validate = function(options) {
        options = options || {};
        
        this.each(function() {
            var $form = $(this);
            
            // Basic form validation
            $form.on('submit', function(e) {
                var valid = true;
                
                // Check required fields
                $form.find('[required]').each(function() {
                    var $field = $(this);
                    if (!$field.val() || $field.val().trim() === '') {
                        valid = false;
                        $field.addClass('is-invalid');
                    } else {
                        $field.removeClass('is-invalid');
                    }
                });
                
                // Check email format
                $form.find('input[type="email"]').each(function() {
                    var $field = $(this);
                    var email = $field.val();
                    if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
                        valid = false;
                        $field.addClass('is-invalid');
                    }
                });
                
                if (!valid && options.submitHandler) {
                    e.preventDefault();
                    return false;
                }
                
                return valid;
            });
        });
        
        return this;
    };
    
    // Basic validation methods
    $.validator = {
        addMethod: function(name, method, message) {
            // Placeholder for addMethod
        }
    };
    
})(jQuery); 